@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:Role ;
                    schema1:roleName [ a schema1:DefinedTerm ;
                            schema1:inDefinedTermSet "https://credit.niso.org/" ;
                            schema1:name "Principal Investigator" ;
                            schema1:termCode "investigation" ] ] ;
            sh:resultMessage "a Role must be filled by a Person, Organization, or IRI reference to one" ;
            sh:resultPath schema1:contributor ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:description "https://cross-domain-interoperability-framework.github.io/cdifbook/metadata/schemaorgimplementation.html" ;
                    sh:message "a Role must be filled by a Person, Organization, or IRI reference to one" ;
                    sh:minCount 1 ;
                    sh:or ( [ sh:class schema1:Person ] [ sh:class schema1:Organization ] [ sh:nodeKind sh:IRI ] ) ;
                    sh:path schema1:contributor ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
